/* CSS Reset and Variables */
:root {
  --primary: #0A0A23;
  --accent: #FEAC32;
  --link: #002EAD;
  --bg-color: #f5f6f7;
  --surface: #ffffff;
  --text-main: #1b1b32;
  --text-light: #858591;
  --border: #d0d0d5;
  --font-family: 'Inter', system-ui, -apple-system, sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.6;
}

a {
  color: var(--link);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

ul {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5 {
  color: var(--primary);
  margin-bottom: 1rem;
  line-height: 1.2;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

/* Global Header */
.global-header {
  background-color: var(--primary);
  color: #fff;
  padding: 1rem 0;
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo a {
  color: #fff;
  font-size: 1.5rem;
  font-weight: bold;
  text-decoration: none;
}

.search-bar {
  flex-grow: 1;
  margin: 0 2rem;
  max-width: 600px;
}

.search-bar input {
  width: 100%;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  border: none;
  font-size: 1rem;
}

.desktop-nav a {
  color: #fff;
  margin-left: 1.5rem;
  text-decoration: none;
}

.desktop-nav a:hover {
  color: var(--accent);
}

.menu-toggle {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  cursor: pointer;
}

.mobile-nav {
  display: none;
  background-color: var(--primary);
  padding: 1rem;
  flex-direction: column;
}

.mobile-nav a {
  color: #fff;
  padding: 0.5rem 0;
  text-decoration: none;
}

.mobile-nav.open {
  display: flex;
}

/* Global Banner */
.global-banner {
  background-color: var(--accent);
  text-align: center;
  padding: 0.75rem;
}

.global-banner a {
  color: var(--primary);
  font-weight: bold;
  font-size: 1.1rem;
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 1rem;
  font-weight: bold;
  text-align: center;
}

.primary-btn {
  background-color: var(--primary);
  color: #fff;
}

.primary-btn:hover {
  background-color: #1b1b32;
  text-decoration: none;
}

.outline-btn {
  background-color: transparent;
  border: 2px solid var(--primary);
  color: var(--primary);
}

.outline-btn:hover {
  background-color: var(--primary);
  color: #fff;
  text-decoration: none;
}

/* Cards */
.article-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 2rem;
  margin: 2rem 0;
}

.article-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  transition: transform 0.2s;
}

.article-card:hover {
  transform: translateY(-4px);
}

.thumbnail {
  height: 200px;
  background-color: #ddd;
}

.card-content {
  padding: 1.5rem;
}

.tag-label {
  display: inline-block;
  background: #e5e5e5;
  color: var(--text-main);
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  font-size: 0.85rem;
  font-weight: bold;
  margin-bottom: 0.75rem;
  text-transform: uppercase;
}

.article-card h3 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
}

.article-card h3 a {
  color: var(--text-main);
}

.author-info {
  display: flex;
  align-items: center;
  font-size: 0.9rem;
  color: var(--text-light);
}

.avatar {
  width: 30px;
  height: 30px;
  background-color: #ccc;
  border-radius: 50%;
  margin-right: 0.5rem;
}

.author-name {
  margin-right: 0.5rem;
  font-weight: bold;
  color: var(--text-main);
}

/* Featured Article */
.featured-article {
  margin: 2rem 0;
}

.featured-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
}

.featured-thumb {
  height: 400px;
}

.featured-card .card-content {
  padding: 2rem;
}

.featured-card h2 {
  font-size: 2rem;
}

.featured-card h2 a {
  color: var(--text-main);
}

.load-more-container {
  text-align: center;
  margin: 2rem 0 4rem;
}

/* Learn Page */
.learn-header {
  text-align: center;
  margin: 3rem 0;
}

.learn-header h2 {
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

.learn-header p {
  font-size: 1.25rem;
  margin-bottom: 1.5rem;
}

.curriculum-list {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  margin-bottom: 2rem;
}

.curriculum-list li {
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  font-size: 1.1rem;
  font-weight: bold;
}

.curriculum-list li:last-child {
  border-bottom: none;
}

.icon {
  margin-right: 0.5rem;
}

.challenge-links {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
}

/* Donate Page */
.donation-hero {
  text-align: center;
  margin: 3rem 0;
}

.donation-form-section {
  display: flex;
  justify-content: center;
  margin-bottom: 3rem;
}

.donation-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 2rem;
  max-width: 500px;
  width: 100%;
  text-align: center;
}

.amount-tabs {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

.amount-btn {
  flex: 1;
  padding: 0.75rem;
  background: #e5e5e5;
  border: none;
  border-radius: 4px;
  font-size: 1.1rem;
  font-weight: bold;
  cursor: pointer;
}

.amount-btn.active {
  background: var(--primary);
  color: #fff;
}

.donation-desc {
  margin-bottom: 1.5rem;
  font-weight: bold;
}

.donate-btn {
  width: 100%;
  background: var(--accent);
  color: var(--primary);
  font-size: 1.25rem;
  margin-bottom: 1rem;
}

.sub-label {
  font-size: 0.9rem;
  color: var(--text-light);
}

.donate-info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 4rem;
}

.donate-info-grid h3 {
  margin-top: 1.5rem;
}

.donate-info-grid ul li {
  margin-bottom: 0.75rem;
  position: relative;
  padding-left: 1.5rem;
}

.donate-info-grid ul li::before {
  content: "•";
  position: absolute;
  left: 0;
  color: var(--primary);
  font-weight: bold;
}

.faq-section h3 {
  margin-top: 0;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 1rem 0;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  color: var(--primary);
}

.faq-answer {
  display: none;
  padding-bottom: 1rem;
  color: var(--text-light);
}

.faq-answer.open {
  display: block;
}

/* Tag Pages */
.tag-header {
  margin: 3rem 0 2rem;
  text-align: center;
}

.tag-header h1 {
  font-size: 2.5rem;
  margin-bottom: 0.5rem;
  text-transform: uppercase;
}

.popular-tags {
  margin-bottom: 2rem;
  overflow-x: auto;
  padding-bottom: 1rem;
}

.tags-scroll {
  display: flex;
  gap: 1rem;
  white-space: nowrap;
}

.pop-tag {
  background: var(--surface);
  border: 1px solid var(--border);
  padding: 0.5rem 1rem;
  border-radius: 20px;
  color: var(--text-main);
  font-weight: bold;
}

.pop-tag:hover {
  background: #e5e5e5;
  text-decoration: none;
}

/* Footer */
.global-footer {
  background: var(--surface);
  border-top: 1px solid var(--border);
  padding: 3rem 0;
  margin-top: 4rem;
  font-size: 0.9rem;
  color: var(--text-light);
}

.global-footer p {
  margin-bottom: 1.5rem;
}

.global-footer a {
  color: var(--text-main);
}

/* Responsive */
@media (max-width: 768px) {
  .desktop-nav, .search-bar {
    display: none;
  }

  .menu-toggle {
    display: block;
  }

  .donate-info-grid {
    grid-template-columns: 1fr;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Menu Toggle
  const menuToggle = document.querySelector('.menu-toggle');
  const mobileNav = document.querySelector('.mobile-nav');

  if (menuToggle && mobileNav) {
    menuToggle.addEventListener('click', () => {
      mobileNav.classList.toggle('open');
    });
  }

  // Load More Articles
  const loadMoreBtn = document.getElementById('load-more-btn');
  const articleGrid = document.getElementById('article-grid');

  if (loadMoreBtn && articleGrid) {
    loadMoreBtn.addEventListener('click', () => {
      const newCard = document.createElement('div');
      newCard.className = 'article-card';
      newCard.innerHTML = `
        <div class="thumbnail"></div>
        <div class="card-content">
          <a href="#" class="tag-label">#new</a>
          <h3><a href="#">Newly Loaded Article Example</a></h3>
          <div class="author-info">
            <div class="avatar"></div>
            <span class="author-name">John Doe</span>
            <span class="timestamp">Just now</span>
          </div>
        </div>
      `;
      articleGrid.appendChild(newCard);
    });
  }

  // Donation Amount Tabs
  const amountBtns = document.querySelectorAll('.amount-btn');
  const donationDesc = document.getElementById('donation-desc');
  const subLabelAmount = document.getElementById('sub-label-amount');

  if (amountBtns.length > 0 && donationDesc && subLabelAmount) {
    amountBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        amountBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const amount = btn.dataset.amount;
        donationDesc.textContent = `Your $${amount} donation will provide ${amount * 50} hours of learning to people around the world each month.`;
        subLabelAmount.textContent = `$${amount}`;
      });
    });
  }

  // FAQ Accordion
  const faqQuestions = document.querySelectorAll('.faq-question');

  if (faqQuestions.length > 0) {
    faqQuestions.forEach(question => {
      question.addEventListener('click', () => {
        const answer = question.nextElementSibling;
        answer.classList.toggle('open');
      });
    });
  }
});
